int checks=0;void check(bool b,const char* why){++checks;if(!b)throw std::runtime_error(why);}
template<class F>void reject(F f){bool bad=false;try{f();}catch(const std::exception&){bad=true;}check(bad,"expected rejection");}
const ToolResult& result(const CycleResult& c,const QString& id){for(const auto& t:c.tools)if(t.toolId==id)return t;throw std::runtime_error("missing tool");}
double number(const ToolResult& r,const QString& id){check(r.outputs.value(id).valid,"valid number");return std::get<double>(r.outputs[id].data);}
void near(double a,double b,double e,const char* why){check(std::abs(a-b)<=e,why);}
